begin
  s1(0) <= B1;
  s1(1) <= B2;
  s1(2) <= B3;
  s1(3) <= B4;
  s0(0) <= A1;
  s0(1) <= A2;
  s0(2) <= A3;
  s0(3) <= A4;
  gate0: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 4)
    port map (
      sel => S,
      in_0 => s0,
      in_1 => s1,
      p_out => s2);
  gate1: entity work.MUX_GATE_BUS_1
    generic map (
