      FLAG_Z => FLAG_Z,
      FLAG_O => FLAG_O,
      COND => COND,
      BRANCH_EN => BRANCH_EN,
      COND_RESULT => COND_RESULT);
  gate1: entity work.sc_control_flags -- SC5-1
    port map (
      INT_EN_IN => INT_EN_IN,
      HALT_IN => HALT_IN,
      INT_REQ => INT_REQ,
      INT_VEC_0 => INT_VEC_0,
      INT_VEC_1 => INT_VEC_1,
      INT_VEC_2 => INT_VEC_2,
      CLK => CLK,
      INT_VECTOR => INT_VECTOR,
      INT_EN => INT_EN,
      HALTED => HALTED,
      INT_GATE => INT_ACK_temp,
      CLK_GATED => CLK_GATED);
  PC_1(0) <= '1';
  PC_1(1) <= '0';
  PC_1(2) <= '0';
  PC_1(3) <= '0';
  PC_1(4) <= '0';
  PC_1(5) <= '0';
  PC_1(6) <= '0';
  PC_1(7) <= '0';
  PC_1(8) <= '0';
  PC_1(9) <= '0';
  PC_1(10) <= '0';
  PC_1(11) <= '0';
  PC_1(12) <= '0';
  PC_1(13) <= '0';
  PC_1(14) <= '0';
  PC_1(15) <= '0';
  PC_1(16) <= '0';
  PC_1(17) <= '0';
  PC_1(18) <= '0';
  PC_1(19) <= '0';
  PC_1(20) <= '0';
  PC_1(21) <= '0';
  PC_1(22) <= '0';
  PC_1(23) <= '0';
  gate2: entity work.sc_flags_save -- SC6-1
    port map (
      INT_GATE => INT_ACK_temp,
      FLAG_N => FLAG_N,
      FLAG_C => FLAG_C,
      FLAG_Z => FLAG_Z,
      FLAG_O => FLAG_O,
      FLAGS_SAVE => FLAGS_SAVE);
  PC_LOAD_N <= NOT (COND_RESULT OR INT_ACK_temp OR JUMP_UNCOND);
  gate3: entity work.sc_pc_counter -- SC1-1
    port map (
      notSR => notSR,
      clk => CLK_GATED,
      notPE => PC_LOAD_N,
      D => LOAD_ADDR,
      pc_en => pc_en,
      Q => PC_OUT_temp);
  gate4: entity work.sc_adder24 -- SC2-2
    port map (
      B => SP_DELTA,
      A => SP_OUT_temp,
      S => SP_D);
  gate5: entity work.sc_pc_counter -- SC1-2
    port map (
      notSR => notSR,
      clk => CLK_GATED,
      notPE => SP_LOAD_N,
      D => SP_D,
      pc_en => pc_en,
      Q => SP_OUT_temp);
  gate6: entity work.sc_adder24 -- SC2-1
    port map (
      B => OFFSET,
      A => PC_OUT_temp,
      S => PC_REL);
  gate7: entity work.sc_mux24_2to1 -- SC3-1
    port map (
      B => PC_REL,
      A => ADDR_ABS,
      SEL => MUX1_SEL,
      Y => L1_OUT);
  gate8: entity work.sc_mux24_2to1 -- SC3-2
    port map (
      B => ADDR_RET,
      A => L1_OUT,
      SEL => MUX2_SEL,
      Y => SC2_2Y);
  gate9: entity work.sc_mux24_2to1 -- SC3-3
    port map (
      B => INT_VECTOR,
      A => SC2_2Y,
      SEL => INT_ACK_temp,
      Y => LOAD_ADDR);
  gate10: entity work.sc_adder24 -- SC2-3
    port map (
      B => PC_1,
      A => PC_OUT_temp,
      S => PC_SAVE);
  PC_OUT <= PC_OUT_temp;
  SP_OUT <= SP_OUT_temp;
  INT_ACK <= INT_ACK_temp;
end Behavioral;

