USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity p_register is
  port (
    WE: in std_logic;
    DATA_W: in std_logic_vector(31 downto 0);
    ADDR_A: in std_logic_vector(7 downto 0);
    ADDR_B: in std_logic_vector(7 downto 0);
    ADDR_W: in std_logic_vector(7 downto 0);
    EXEC: in std_logic;
    addr_c_sel: in std_logic;
    IR_ADDR_CIN: in std_logic_vector(7 downto 0);
    clk: in std_logic;
    DATA_A: out std_logic_vector(31 downto 0);
    DATA_B: out std_logic_vector(31 downto 0);
    DATA_C: out std_logic_vector(31 downto 0));
end p_register;

architecture Behavioral of p_register is
  signal ram_and: std_logic;
  signal ADDR_C: std_logic_vector(7 downto 0);
  signal n0x00: std_logic_vector(7 downto 0);
begin
  ram_and <= (EXEC AND WE);
  n0x00(0) <= '0';
  n0x00(1) <= '0';
  n0x00(2) <= '0';
  n0x00(3) <= '0';
  n0x00(4) <= '0';
  n0x00(5) <= '0';
  n0x00(6) <= '0';
  n0x00(7) <= '0';
  gate0: entity work.DIG_RAMDualAccess -- U1
    generic map (
      Bits => 32,
      AddrBits => 8)
    port map (
      str => ram_and,
      C => clk,
      ld => '1',
      n1A => ADDR_W,
      n1Din => DATA_W,
      n2A => ADDR_A,
      n2D => DATA_A);
  gate1: entity work.DIG_RAMDualAccess -- U2
    generic map (
      Bits => 32,
      AddrBits => 8)
    port map (
      str => ram_and,
      C => clk,
      ld => '1',
      n1A => ADDR_W,
      n1Din => DATA_W,
      n2A => ADDR_B,
      n2D => DATA_B);
  gate2: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 8)
    port map (
      sel => addr_c_sel,
      in_0 => n0x00,
      in_1 => IR_ADDR_CIN,
      p_out => ADDR_C);
  gate3: entity work.DIG_RAMDualAccess -- U3
    generic map (
      Bits => 32,
      AddrBits => 8)
    port map (
      str => ram_and,
      C => clk,
      ld => '1',
      n1A => ADDR_W,
      n1Din => DATA_W,
      n2A => ADDR_C,
      n2D => DATA_C);
end Behavioral;

