entity flag_reg is
  port (
    ZERO_IN: in std_logic;
    CARRY_IN: in std_logic;
    NEGATIVE_IN: in std_logic;
    OVERFLOW_IN: in std_logic;
    FLAG_WE: in std_logic;
    CLK: in std_logic;
    EXEC: in std_logic;
    FLAG_Z: out std_logic;
    FLAG_C: out std_logic;
    FLAG_N: out std_logic;
    FLAG_O: out std_logic);
end flag_reg;

architecture Behavioral of flag_reg is
  signal CLK_GATED: std_logic;
  signal FLAG_Z_N: std_logic;
  signal FLAG_C_N: std_logic;
  signal FLAG_NN: std_logic;
  signal FLAG_O_N: std_logic;
begin
  CLK_GATED <= (CLK AND EXEC AND FLAG_WE);
  gate0: entity work.n7474
    port map (
      not1RD => '1',
      n1D => ZERO_IN,
      n1CP => CLK_GATED,
      not1SD => '1',
      GND => '0',
      not2SD => '1',
      n2CP => CLK_GATED,
      n2D => CARRY_IN,
      not2RD => '1',
      VCC => '1',
      n1Q => FLAG_Z,
      not1Q => FLAG_Z_N,
      not2Q => FLAG_C_N,
      n2Q => FLAG_C);
  gate1: entity work.n7474
    port map (
      not1RD => '1',
      n1D => NEGATIVE_IN,
      n1CP => CLK_GATED,
      not1SD => '1',
      GND => '0',
      not2SD => '1',
      n2CP => CLK_GATED,
      n2D => OVERFLOW_IN,
      not2RD => '1',
      VCC => '1',
      n1Q => FLAG_N,
      not1Q => FLAG_NN,
      not2Q => FLAG_O_N,
      n2Q => FLAG_O);
end Behavioral;

