entity wb_mux is
  port (
    wb_sel: in std_logic_vector(1 downto 0);
    alu_out: in std_logic_vector(31 downto 0);
    shift_out: in std_logic_vector(31 downto 0);
    pc_save: in std_logic_vector(23 downto 0);
    mem_din: in std_logic_vector(31 downto 0);
    reg_w_data: out std_logic_vector(31 downto 0));
end wb_mux;

architecture Behavioral of wb_mux is
  signal pc_save_32: std_logic_vector(31 downto 0);
begin
  pc_save_32(23 downto 0) <= pc_save;
  pc_save_32(24) <= '0';
  pc_save_32(25) <= '0';
  pc_save_32(26) <= '0';
  pc_save_32(27) <= '0';
  pc_save_32(28) <= '0';
  pc_save_32(29) <= '0';
  pc_save_32(30) <= '0';
  pc_save_32(31) <= '0';
  gate0: entity work.MUX_GATE_BUS_2
    generic map (
      Bits => 32)
    port map (
      sel => wb_sel,
      in_0 => alu_out,
      in_1 => shift_out,
      in_2 => pc_save_32,
      in_3 => mem_din,
      p_out => reg_w_data);
end Behavioral;

LIBRARY ieee;
USE ieee.std_logic_1164.all;

entity DIG_Register_BUS is
  generic ( Bits: integer ); 
  port (
    Q: out std_logic_vector ((Bits-1) downto 0);
    D: in std_logic_vector ((Bits-1) downto 0);
    C: in std_logic;
    en: in std_logic );
end DIG_Register_BUS;

architecture Behavioral of DIG_Register_BUS is
  signal state : std_logic_vector ((Bits-1) downto 0) := (others => '0');
begin
   Q <= state;

   process ( C )
   begin
      if rising_edge(C) and (en='1') then
        state <= D;
      end if;
   end process;
end Behavioral;


