entity ir3 is
  port (
    DATA_IN: in std_logic_vector(31 downto 0);
    LOAD: in std_logic;
    CLK: in std_logic;
    IR_BUS: out std_logic_vector(31 downto 0);
    OPCODE: out std_logic_vector(7 downto 0);
    ADDR_A: out std_logic_vector(7 downto 0);
    ADDR_B: out std_logic_vector(7 downto 0);
    ADDR_W: out std_logic_vector(7 downto 0);
    ADDR_ABS: out std_logic_vector(23 downto 0);
    OFFSET: out std_logic_vector(23 downto 0);
    COND: out std_logic_vector(2 downto 0);
    MUX1_SEL: out std_logic;
    MUX2_SEL: out std_logic);
end ir3;

architecture Behavioral of ir3 is
  signal IR_BUS_temp: std_logic_vector(31 downto 0);
  signal OFFSET_temp: std_logic_vector(23 downto 0);
begin
  gate0: entity work.DIG_Register_BUS
    generic map (
      Bits => 32)
    port map (
      D => DATA_IN,
      C => CLK,
