LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity microcode is
  port (
    op: in std_logic_vector(7 downto 0);
    alu_op: out std_logic_vector(7 downto 0);
    alu_pre: out std_logic_vector(4 downto 0);
    cin_sel: out std_logic;
    wb_sel: out std_logic_vector(1 downto 0);
    shift_op: out std_logic_vector(1 downto 0);
    flags_we: out std_logic;
    reg_we: out std_logic;
    mem_rd: out std_logic;
    mem_wr: out std_logic;
    addr_csel: out std_logic;
    branch_en: out std_logic;
    jump_type: out std_logic;
    sp_op: out std_logic_vector(1 downto 0);
    cycles: out std_logic_vector(1 downto 0);
    unused: out std_logic_vector(1 downto 0);
    b_main_sel: out std_logic);
end microcode;

architecture Behavioral of microcode is
  signal s0: std_logic_vector(31 downto 0);
begin
  gate0: entity work.DIG_ROM_microcodeeeprom -- microcode eeprom
    port map (
      A => op,
      sel => '1',
      D => s0);
  alu_op <= s0(7 downto 0);
  alu_pre <= s0(12 downto 8);
  cin_sel <= s0(13);
  wb_sel <= s0(15 downto 14);
  shift_op <= s0(17 downto 16);
  flags_we <= s0(18);
  reg_we <= s0(19);
  mem_rd <= s0(20);
  mem_wr <= s0(21);
  addr_csel <= s0(22);
  branch_en <= s0(23);
  jump_type <= s0(24);
  sp_op <= s0(26 downto 25);
  cycles <= s0(28 downto 27);
  b_main_sel <= s0(29);
  unused <= s0(31 downto 30);
end Behavioral;

LIBRARY ieee;
USE ieee.std_logic_1164.all;

entity COMP_GATE_UNSIGNED is
  generic ( Bits : integer );
  port (
    gr: out std_logic;
    eq: out std_logic;
    le: out std_logic;
    a: in std_logic_vector ((Bits-1) downto 0);
    b: in std_logic_vector ((Bits-1) downto 0) );
end COMP_GATE_UNSIGNED;

architecture Behavioral of COMP_GATE_UNSIGNED is
begin
  process(a, b)
  begin
    if (a > b ) then
      le <= '0';
      eq <= '0';
      gr <= '1';
    elsif (a < b) then
      le <= '1';
      eq <= '0';
      gr <= '0';
    else
      le <= '0';
      eq <= '1';
      gr <= '0';
    end if;
  end process;
end Behavioral;


LIBRARY ieee;
USE ieee.std_logic_1164.all;

entity DRIVER_INV_GATE_BUS is
  generic ( Bits : integer ); 
  port (
    p_out: out std_logic_vector ((Bits-1) downto 0);
    p_in: in std_logic_vector ((Bits-1) downto 0);
    sel: in std_logic );
end DRIVER_INV_GATE_BUS;

architecture Behavioral of DRIVER_INV_GATE_BUS is
begin
  p_out <= p_in when sel = '0' else (others => 'Z');
end Behavioral;


LIBRARY ieee;
USE ieee.std_logic_1164.all;

entity DRIVER_INV_GATE_BUS is
  generic ( Bits : integer ); 
  port (
