    sel: in std_logic );
end DRIVER_INV_GATE_BUS;

architecture Behavioral of DRIVER_INV_GATE_BUS is
begin
  p_out <= p_in when sel = '1' else (others => 'Z');
end Behavioral;


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity mmio_bus is
  port (
    ADDR: in std_logic_vector(23 downto 0);
    CPU_ADDR_OUT: out std_logic_vector(23 downto 0);
    mmio_addr: out std_logic_vector(23 downto 0);
    is_mmio: out std_logic);
end mmio_bus;

architecture Behavioral of mmio_bus is
  signal s0: std_logic_vector(3 downto 0);
  signal is_mmio_temp: std_logic;
begin
  s0 <= ADDR(23 downto 20);
  gate0: entity work.COMP_GATE_UNSIGNED
    generic map (
      Bits => 4)
    port map (
      a => s0,
      b => "1111",
      eq => is_mmio_temp);
  gate1: entity work.DRIVER_INV_GATE_BUS
    generic map (
      Bits => 24)
    port map (
      p_in => ADDR,
      sel => is_mmio_temp,
      p_out => CPU_ADDR_OUT);
  gate2: entity work.DRIVER_INV_GATE_BUS
    generic map (
      Bits => 24)
    port map (
      p_in => ADDR,
      sel => is_mmio_temp,
      p_out => mmio_addr);
  is_mmio <= is_mmio_temp;
end Behavioral;

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity DIG_RAMDualPort is
  generic (
    Bits : integer;       
    AddrBits : integer ); 
  port (
    D: out std_logic_vector ((Bits-1) downto 0);
    A: in std_logic_vector ((AddrBits-1) downto 0);
    Din: in std_logic_vector ((Bits-1) downto 0);
    str: in std_logic;
    C: in std_logic;
    ld: in std_logic );
end DIG_RAMDualPort;

architecture Behavioral of DIG_RAMDualPort is
    -- CAUTION: uses distributed RAM
    type memoryType is array(0 to (2**AddrBits)-1) of STD_LOGIC_VECTOR((Bits-1) downto 0);
    signal memory : memoryType;
begin
  process ( C )
  begin
    if rising_edge(C) AND (str='1') then
      memory(to_integer(unsigned(A))) <= Din;
    end if;
  end process;
  D <= memory(to_integer(unsigned(A))) when ld='1' else (others => 'Z');
end Behavioral;


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity memory is
  port (
    ADDR: in std_logic_vector(23 downto 0);
    MEM_RD: in std_logic;
    MEM_WR: in std_logic;
    CLK: in std_logic;
    CPU_DIN: in std_logic_vector(31 downto 0);
    CPU_D_OUT: out std_logic_vector(31 downto 0));
end memory;

architecture Behavioral of memory is
  signal notWE: std_logic;
  signal notOE: std_logic;
begin
  notWE <= NOT MEM_WR;
  notOE <= NOT MEM_RD;
  gate0: entity work.DIG_RAMDualPort
    generic map (
      Bits => 32,
      AddrBits => 24)
    port map (
      A => ADDR,
      Din => CPU_DIN,
      str => MEM_WR,
      C => CLK,
      ld => MEM_RD,
      D => CPU_D_OUT);
end Behavioral;

