entity io_controller is
  port (
    mem_addr: in std_logic_vector(23 downto 0);
    c_wr: in std_logic;
    kb_data: in std_logic_vector(15 downto 0);
    mem_data_out: in std_logic_vector(31 downto 0);
    io_data_in: out std_logic_vector(31 downto 0);
    ram_cs: out std_logic;
    vram_we: out std_logic;
    vram_addr: out std_logic_vector(15 downto 0);
    vram_data: out std_logic_vector(15 downto 0);
    term_we: out std_logic;
    term_data: out std_logic_vector(15 downto 0));
end io_controller;

architecture Behavioral of io_controller is
  signal comp2_eq: std_logic;
  signal comp3_gr: std_logic;
  signal comp3_eq: std_logic;
  signal comp4_eq: std_logic;
  signal comp4_le: std_logic;
  signal c_kb_in: std_logic_vector(31 downto 0);
begin
  gate0: entity work.COMP_GATE_UNSIGNED
    generic map (
      Bits => 24)
    port map (
      a => mem_addr,
      b => "100000000000000000000000",
      le => ram_cs);
  gate1: entity work.COMP_GATE_UNSIGNED
    generic map (
      Bits => 24)
    port map (
      a => mem_addr,
      b => "100000000000000000010000",
      eq => comp2_eq);
  gate2: entity work.COMP_GATE_UNSIGNED
    generic map (
      Bits => 24)
    port map (
      a => mem_addr,
      b => "111100000000000000000000",
      gr => comp3_gr,
      eq => comp3_eq);
  gate3: entity work.COMP_GATE_UNSIGNED
    generic map (
      Bits => 24)
    port map (
      a => mem_addr,
      b => "100000000000000000010100",
      eq => comp4_eq,
      le => comp4_le);
  c_kb_in(15 downto 0) <= kb_data;
  c_kb_in(31 downto 16) <= "0000000000000000";
  term_data <= mem_data_out(15 downto 0);
  vram_addr <= mem_addr(15 downto 0);
  vram_data <= mem_data_out(15 downto 0);
  term_we <= (comp2_eq AND c_wr);
  vram_we <= ((comp3_gr OR comp3_eq) AND c_wr);
  gate4: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 32)
    port map (
      sel => comp4_eq,
      in_0 => "00000000000000000000000000000000",
      in_1 => c_kb_in,
      p_out => io_data_in);
end Behavioral;

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;

entity alu_1b_final is
  port (
    OPCODE: in std_logic_vector(7 downto 0);
    A: in std_logic;
    B: in std_logic;
    C: in std_logic;
    Asel: in std_logic;
    Bsel: in std_logic;
    A_inv: in std_logic;
    B_inv: in std_logic;
    MUX_OUT: out std_logic;
    G: out std_logic;
    P: out std_logic);
end alu_1b_final;

architecture Behavioral of alu_1b_final is
  signal s0: std_logic_vector(2 downto 0);
  signal s1: std_logic;
  signal s2: std_logic;
  signal s3: std_logic;
  signal s4: std_logic;
  signal s5: std_logic;
  signal s6: std_logic;
  signal s7: std_logic;
  signal s8: std_logic;
  signal B_eff: std_logic;
  signal A_eff: std_logic;
begin
  A_eff <= ((Asel AND A) XOR A_inv);
  B_eff <= ((Bsel AND B) XOR B_inv);
  s1 <= OPCODE(0);
  s2 <= OPCODE(1);
  s3 <= OPCODE(2);
  s4 <= OPCODE(3);
  s5 <= OPCODE(4);
  s6 <= OPCODE(5);
  s7 <= OPCODE(6);
  s8 <= OPCODE(7);
  s0(0) <= C;
  s0(1) <= B_eff;
  s0(2) <= A_eff;
  G <= (A_eff AND B_eff);
  P <= (A_eff OR B_eff);
  gate0: entity work.MUX_GATE_3
    port map (
      sel => s0,
      in_0 => s1,
      in_1 => s2,
      in_2 => s3,
      in_3 => s4,
      in_4 => s5,
      in_5 => s6,
      in_6 => s7,
      in_7 => s8,
      p_out => MUX_OUT);
end Behavioral;

