    n4A: in std_logic;
    n4B: in std_logic;
    VCC: in std_logic;
    GND: in std_logic;
    n1Y: out std_logic;
    n2Y: out std_logic;
    n3Y: out std_logic;
    n4Y: out std_logic);
end n7408;

architecture Behavioral of n7408 is
begin
  n1Y <= (n1A AND n1B);
