-- look-ahead carry generator
entity n74182 is
  port (
    C_n: in std_logic;
    notG0: in std_logic;
    notP0: in std_logic;
    notG1: in std_logic;
    notP1: in std_logic;
    notG2: in std_logic;
    notP2: in std_logic;
    notG3: in std_logic;
    notP3: in std_logic;
    VCC: in std_logic;
    GND: in std_logic;
    notP: out std_logic;
    notG: out std_logic;
    C_n_z: out std_logic;
    C_n_y: out std_logic;
    C_n_x: out std_logic);
end n74182;

architecture Behavioral of n74182 is
  signal s0: std_logic;
begin
  notP <= (notP0 OR notP1 OR notP2 OR notP3);
  notG <= ((notG0 AND notG1 AND notG2 AND notG3) OR (notP1 AND notG3 AND notG2 AND notG1) OR (notP2 AND notG3 AND notG2) OR (notP3 AND notG3));
  s0 <= NOT C_n;
  C_n_z <= NOT ((notG2 AND notG1 AND notG0 AND s0) OR (notP0 AND notG2 AND notG1 AND notG0) OR (notP1 AND notG2 AND notG1) OR (notP2 AND notG2));
  C_n_y <= NOT ((notG1 AND notG0 AND s0) OR (notP0 AND notG1 AND notG0) OR (notP1 AND notG1));
  C_n_x <= NOT ((notG0 AND s0) OR (notP0 AND notG0));
end Behavioral;

