entity DRIVER_INV_GATE is
  
  port (
    p_out: out std_logic;
    p_in: in std_logic;
    sel: in std_logic );
end DRIVER_INV_GATE;

architecture Behavioral of DRIVER_INV_GATE is
begin
  p_out <= p_in when sel = '1' else 'Z';
end Behavioral;


