      p_in => s4,
      sel => s1,
      p_out => n3O);
  gate4: entity work.DRIVER_INV_GATE
    port map (
      p_in => s5,
      sel => s1,
      p_out => n4O);
  gate5: entity work.DRIVER_INV_GATE
    port map (
      p_in => s6,
      sel => s1,
      p_out => n5O);
  gate6: entity work.DRIVER_INV_GATE
    port map (
      p_in => s7,
      sel => s1,
      p_out => n6O);
  gate7: entity work.DRIVER_INV_GATE
    port map (
